mapper.update:
UPDATE asset
asset_owner_id = #{assetOwnerId}, asset_name = #{assetName}, asset_type = #{assetType}, asset_due_time = #{assetDueTime}, asset_status = #{assetStatus}, asset_area = #{assetArea}, asset_building = #{assetBuilding}, asset_floor = #{assetFloor}, asset_position = #{assetPosition}, asset_remark = #{assetRemark},
WHERE id = #{id}

mapper.select:
SELECT a.*, u.user_name AS owner_name, at2.asset_type_name FROM asset a LEFT JOIN user u ON a.asset_owner_id = u.id LEFT JOIN asset_type at2 ON a.asset_type = at2.asset_type_id
AND a.asset_owner_id = #{assetOwnerId}
AND a.asset_type = #{assetType}
AND a.asset_status = #{assetStatus}
AND a.asset_building LIKE CONCAT('%', #{assetBuilding}, '%')
ORDER BY a.asset_reg_time DESC

SELECT a.*, u.user_name AS owner_name, at2.asset_type_name FROM asset a LEFT JOIN user u ON a.asset_owner_id = u.id LEFT JOIN asset_type at2 ON a.asset_type = at2.asset_type_id
AND a.asset_owner_id = #{assetOwnerId}
ORDER BY a.asset_reg_time DESC
